          "before": "",
          "after": "den rutinerade ordenskännaren för den stundande reorganisationen och utvidgningen. C. blef sålunda en af P. B:s äldste »gouverneurer» och utnämndes till Riddare af Bricoleriet näst efter de två föregående. Efter Kexéls död, då P. B. skulle ytterligare utvidgas med en högre afdelning, var Cederstedt den som ledde organisationsarbetet och författade de tre högsta riddargradernas ritualer samt 25 sept. 1799 tillträdde det nyinrättade Stormästareembetet, som han bibehöll till sin död. Något egentligt porträtt af denne brikolchef finnes icke, endast den här reproducerade karrikatyren från sekelskiftet. »Cederstedt hade lyckliga naturgåfvor, var fintlig att se Dårskapen, dristig att röja henne, skicklig att framställa henne i hela sin Caricaturiska vidunderlighet, var mägtigt verksam att sprida detta löje, i synnerhet som hans meddelande lynne öppnade för honom alla kretsar, dit han i de höga medförde en otvungen öppenhjertighet, i de lägre ett språk, alltid lämpadt efter dem, som omgåfvo honom.» Bomans minnestal. 5 4. STIERNECRANTZ, GUSTAV (FABIAN). Capitain. F. 5 febr. 1751 i Stockholm, † derst. 29 juli 1800. »En carolin Arved Stiernecrantz återkom från rysk fångenskap 1722 med en son vid sin hand», berättar en gammal"
