      "revision": 2,
      "parentRevision": 1,
      "status": "proofread",
      "segments": [
        "32\nTAL\npå Barbara-dagen, den 4 December 1784, hållet på Claës på hörnet af Cornetten Arvid Adrian Stjernecrantz.\n\nFöraktliga flock, som kryper på ett af de mindsta bland de myriader klot som hvimla i den ogränseliga rymden! Du, som under namn af menniska bröstar dig af en höghet, den ditt eget uppförande förnekar! Du, som danad att njuta nöjet i sin förtjusning och sanningen i sin renhet, stundeligen använder din omsorg endast att smärtas och förvillas! Du, som borde andas din egen sällhet i din grannes väl, i din väns trefnad, men fröjdas vid hans fall och segrar, då du trampar honom på hjessan. Du, som fått ett hjerta, för att öma, och ett sköte för att omarma och skydda den olycklige, men förhärdar din själ till en klippa och fördubblar den betrycktes börda med ditt stolta förakt, endast derföre, att du ännu icke varit i lika belägenhet! Du kräfver, att allt skall vara till din tjenst och anser den obetydligaste handräckning du sjelf gör som det utmärktaste ädelmod! Du, som ej känner något lagom, åtminstone intet öfverflöd för de behof dårskapen, vällusten och tusen nycker måla för ditt lystna öga, då du anser den uslaste lott mer än tillräckelig för din torftige like! Du, som skryter af vishet och styrka, men behöfver ej mer än några blickar af två vackra ögon, för att blifva en fullkomlig dåre. Du, som är skapad för naturen, der förställning och bojor äro de första, som emottaga dig! Föraktliga flock! bör",
        "33\nman undra att floder dränka dig och brinnande afgrunder öppna sina svalg under dina dårskaper och omenskligheter? Må heldre mitt slägte sluta här, der det skulle återbörja, än min efterverld skulle likna min forn- och samtid.»\n\nDe bedröfliga vedermälen af den allmänna floden, som en dag mera lifligt föllo Noak i ögonen, aftvungo honom dessa förbittrade, fast tyvärr! riktiga betraktelser. Fördjupad i sin nitälskan mot detta usla slägte hade han ännu fortsatt sina filosofiska granskningar, om ej en vacker röst afbrutit dem genom denna af oss kända muntran:\n\n»Kom, kära granne, sätt dig ner\nOch tag ditt glas och pipa\nKom, låt oss nästra allt som sker\nFast vi det ej begripa» 1).\n\nVäckt, likasom ur en dvala, stadnade han och med en häpen förundran betraktade den hydda, der han likväl, i Bacchi armar och Fröjas sköt, njutit så många oskattbara stunder. Med möda kände han igen sin egen fru, hvilken var den sirén, som nu förtjuste honom, och oansedt verlden ej bestod af mer än åtta menniskor hade han säkert i sin förvirring förnekat sin egen hälft, om hon ej tydeligen öfvertygat honom hvem hon var, medelst hemliga sigillets uppvisande. Noak trodde sig hela milen från sitt hem, men hade endast genom krok- och bivägar kringvandrat en dervid liggande bergskulle. Räknom honom ej detta till svaghet! det är merendels alla filosofers öde: när de genom tusen omvägar tro sig hunnit ett mål, äro de oftast, uttröttade och förvillade, på sitt första ställe."
      ],
