          "before": "",
          "after": "med skäl tviflar ha varit till. I anseende härtill har han ock ett utvaldt bibliothek af alla slags oläsliga böcker och manuscripter; och det är här jag egenteligen träffat de källor, utur hvilka jag någon gång tänker hemta och utarbeta Fru Barbara Noaks äreminne, hvaraf jag i dag, som hastigast, vill meddela försök till ett utkast. Den ena är en rimkrönika före syndafloden, och den andra en Filosofico-Etymologico-Genealogico-Chronologico-historisk likpredikan, med tillhörande personalier, hållen öfver Fru Barbara Noak i Carpentras’ kyrka i Frankrike, der hon ligger begrafven, och det säges, att hennes kista ännu är att bese, fastän tom, nescio quo casu. Detta är en af de omständigheter, som ökar författarens trovärdighet. Ty han säger i sitt företal, att Carpentras (eller Charpentras) 35 har just sitt namn af desse skeppstimmermän och den graf de här beredt sin hustru och mor. Kan väl större historisk sannfärdighet ges? Jag åberopar mig salig Professor Rudbeck och hans Atlantica. Men huruledes kistan blifvit tom måga andra undersöka. Det kunde, till exempel, skett af våda någon gång, då grafven ommurades. Detta är dock blott en gissning. Sannolikare är, att man här träffar spår till någon snikenhet hos några arfvingar, eller tilläfventyrs hos sjelfva Dom-Capitlet, hvaraf sednare tider försett oss med exempel från Linköping. Mitt egenteliga föremål blir då här att visa den ärorika stam, utur hvilken en så ädel blomma som vår Barbara leder sitt ursprung. Alla hafva varit Bacchi hjeltar, som ej underlåtit, att vid hans altare äfven knäböja för Fröja. Att med mina"
