        "notes": [
          "Not 1 fortsätter från vänster till höger boksida. Not 2 och 3 hör till tidigare text utanför urvalet."
        ],
        "revision": 2,
        "parentRevision": 1,
        "status": "proofread",
        "segments": [
          "30\nARIA.\n(Mel.: Min vän, jag ropar dig &c.)\nMin näsduk är helt våt\nKan tänka utaf gråt\nOch heta tårar.\nKexél i Bacchi gård,\nDu var en trogen vård,\nDet oss nu sårar.\n\nKexél! jag gråter dig,\nHvar gång jag lägger mig\nHvar gång jag vaknar.\nDen vän jag fordom vannt\nVid Bischoffsbålens kant\nNu ömt jag saknar.\n\nCHORUS.\nCapitlet oss ej roar mer\nDå man Kexél der icke ser\nSom glädtigt vid sin flaska ler.\nPunsch har alltid något fel\nNär den ej brygges af Kexél.\nNågot Kronobränneri\nBorde köpa honom fri.\n\n1) Arvid Adrian Stjernecrantz, född 1755, Cornett och Lif-Drabant, »en ledigt versgörande, föga poësihaltig, men ingalunda oqvick Bellmannian», som Atterbom benämner honom i Svenska Siare och Skalder, var Kexéls förnämsta",
          "31\nbiträde vid stiftandet af P. B. och till sin död, den 13 Martii 1785, en bland de mest nitiskt arbetande i detta sällskap, vid hvars sammankomster foster af hans lediga, okonstlade men ofta satiriska penna sällan saknades. Få af hans arbeten äro tryckta, utom i dagblad och ströskrifter.\n\n2) Läses som tuppen gal.\n3) En skrift, hvarför Kexél, »för hårda och ogrundade »tillvitelser mot tidens Presterskap i gemen och obehöriga »tillåtelser mot öfrige medborgare i Riket» dömdes (1769) att böta 300 daler silfvermynt."
        ],
