            "before": "• •",
            "after": "32 TAL på Barbara-dagen, den 4 December 1784, hållet på Claës på hörnet af Cornetten Arvid Adrian Stjernecrantz. Föraktliga flock, som kryper på ett af de mindsta bland de myriader klot som hvimla i den ogränseliga rymden! Du, som under namn af menniska bröstar dig af en höghet, den ditt eget uppförande förnekar! Du, som danad att njuta nöjet i sin förtjusning och sanningen i sin renhet, stundeligen använder din omsorg endast att smärtas och förvillas! Du, som borde andas din egen sällhet i din grannes väl, i din väns trefnad, men fröjdas vid hans fall och segrar, då du trampar honom på hjessan. Du, som fått ett hjerta, för att öma, och ett sköte för att omarma och skydda den olycklige, men förhärdar din själ till en klippa och fördubblar den betrycktes börda med ditt stolta förakt, endast derföre, att du ännu icke varit i lika belägenhet! Du kräfver, att allt skall vara till din tjenst och anser den obetydligaste handräckning du sjelf gör som det utmärktaste ädelmod! Du, som ej känner något lagom, åtminstone intet öfverflöd för de behof dårskapen, vällusten och tusen nycker måla för ditt lystna öga, då du anser den uslaste lott mer än tillräckelig för din torftige like! Du, som skryter af vishet och styrka, men behöfver ej mer än några blickar af två vackra ögon, för att blifva en fullkomlig dåre. Du, som är skapad för naturen, der förställning och bojor äro de första, som emottaga dig! Föraktliga flock! bör"
